mapper.insert:
INSERT INTO agent_task (
    tenant_id, name, agent_id, agent_name, prompt, cron_expression,
    task_status, concurrent, timeout_seconds, description,
    is_public, creator, active, create_time, update_time
) VALUES (
    #{tenantId}, #{name}, #{agentId}, #{agentName}, #{prompt}, #{cronExpression},
    #{taskStatus}, #{concurrent}, #{timeoutSeconds}, #{description},
    #{isPublic}, #{creator}, #{active}, #{createTime}, #{updateTime}
)

mapper.select:
SELECT t.*, latest.status AS last_run_status, latest.start_time AS last_run_time FROM agent_task t LEFT JOIN ( SELECT l1.task_id, l1.status, l1.start_time FROM agent_task_log l1 INNER JOIN ( SELECT task_id, MAX(id) AS max_id FROM agent_task_log GROUP BY task_id ) l2 ON l1.id = l2.max_id ) latest ON t.id = latest.task_id WHERE t.active = 1 AND (t.is_public = 1 OR t.creator = #{currentUsername})
AND t.name LIKE CONCAT('%', #{name}, '%')
AND t.agent_id = #{agentId}
AND t.task_status = #{taskStatus}
ORDER BY t.update_time DESC
